// Builds one search job per topic and format. Runs once per execution.
// State lives in workflow static data. n8n only saves it on production runs, not on manual test runs.
const cfg = $input.first().json;
const state = $getWorkflowStaticData('global');
state.topics = state.topics || {};
state.phrases = state.phrases || {};
state.runQuota = null;   // transient: remaining daily credits, set by the fetch loop
state.runAbort = false;  // transient: set after a fatal API error so remaining searches are skipped
state.runDropped = [];   // transient: jobs dropped because of the credit budget

const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const isTrue = v => v === true || String(v).toLowerCase() === 'true';

const topics = [...new Set(String(cfg.topics || '').split(/\r?\n/).map(t => t.trim().toLowerCase()).filter(Boolean))];
if (topics.length === 0) {
  throw new Error('No topics configured. Add at least one topic (one per line) in "Set Trend Config".');
}
const formats = isTrue(cfg.includeShorts) ? ['video', 'shorts'] : ['video'];

// Credit budget: every page costs one credit, so shrink the page cap (and, if needed, drop jobs).
const maxCredits = Math.max(1, num(cfg.maxCreditsPerRun, 15));
let jobs = [];
for (const topic of topics) for (const format of formats) jobs.push({ topic, format });
if (jobs.length > maxCredits) {
  state.runDropped = jobs.slice(maxCredits).map(j => j.topic + ' (' + j.format + ')');
  jobs = jobs.slice(0, maxCredits);
}
const maxPages = Math.max(1, Math.min(num(cfg.maxPagesPerSearch, 3), Math.floor(maxCredits / jobs.length)));

const now = Date.now();
const out = jobs.map(j => {
  const ts = state.topics[j.topic];
  const watermark = ts && ts.watermark ? ts.watermark : null;
  const elapsedMin = ts && ts.lastRunAt ? (now - ts.lastRunAt) / 60000 : null;
  // Use the last-hour filter for on-time hourly runs. If the last successful run is more than 70 minutes
  // ago (missed or failed run), widen the filter so the gap is recovered. The watermark removes duplicates.
  let uploadDate = 'hour';
  if (elapsedMin !== null && elapsedMin > 70) uploadDate = elapsedMin <= 1380 ? 'today' : (elapsedMin <= 9000 ? 'week' : 'month');
  return { json: { topic: j.topic, format: j.format, uploadDate, watermark, maxPages, pages: 0, posts: [], token: '' } };
});
return out;

// Entry point for every page request (first page and follow-up pages).
// Marks the job as skipped when the quota is low or a fatal API error already happened in this run.
const cfg = $('Set Trend Search Config').first().json;
const state = $getWorkflowStaticData('global');
const job = { ...$json };
job.pages = job.pages || 0;
job.posts = job.posts || [];
job.token = job.token || '';
const minQuota = Number(cfg.minQuotaRemaining);
if (state.runAbort) {
  job.skipped = true;
  job.skipReason = 'skipped after a fatal API error earlier in this run';
} else if (typeof state.runQuota === 'number' && Number.isFinite(minQuota) && state.runQuota < minQuota) {
  job.skipped = true;
  job.skipReason = 'skipped because the remaining daily quota (' + state.runQuota + ') is below ' + minQuota;
}
return [{ json: job }];

// Reads one page of results, keeps only posts newer than the watermark, and decides whether to fetch another page.
// Results come back newest first, so a post at or before the watermark means we have caught up.
const cfg = $('Set Trend Search Config').first().json;
const state = $getWorkflowStaticData('global');
const job = { ...$('Prepare Page Requests').last().json };
const res = $input.first().json || {};
const headers = res.headers || {};
const body = res.body;
const minQuota = Number(cfg.minQuotaRemaining);

const rem = headers['x-ratelimit-remaining'];
const remaining = rem !== undefined && rem !== '' && Number.isFinite(Number(rem)) ? Number(rem) : null;
if (remaining !== null) { state.runQuota = remaining; job.quotaRemaining = remaining; }

if (!body || !Array.isArray(body.results)) {
  job.failed = true;
  job.error = 'Unexpected response (no results array): ' + JSON.stringify(body || {}).slice(0, 200);
  job.more = false;
  return [{ json: job }];
}

const wm = job.watermark ? Date.parse(job.watermark) : null;
const seen = new Set(job.posts.map(p => p.url));
let reached = false;
for (const r of body.results) {
  if (!r || !r.url) continue;
  const t = Date.parse(r.posted_at);
  if (wm !== null && !isNaN(t) && t <= wm) { reached = true; continue; }
  if (seen.has(r.url)) continue;
  seen.add(r.url);
  job.posts.push({
    url: r.url,
    title: String(r.caption || '').slice(0, 200),
    author: r.author || '',
    author_id: r.author_id || '',
    posted_at: r.posted_at || null
  });
}

job.pages += 1;
const token = body.next_pagination_token || '';
const quotaLow = remaining !== null && Number.isFinite(minQuota) && remaining < minQuota;
const more = Boolean(token) && !reached && job.pages < job.maxPages && !quotaLow;
// capped = there were still older unseen posts, but the page cap or quota stopped us (the count is a lower bound)
job.capped = Boolean(token) && !reached && !more;
job.token = more ? token : '';
job.more = more;
return [{ json: job }];

// Converts a failed request into a marker item so the loop continues and all problems
// are reported together. Auth, plan, parameter and rate-limit errors abort the rest of the run.
const job = { ...$('Prepare Page Requests').last().json };
const state = $getWorkflowStaticData('global');
const err = $input.first().json.error;
const message = (err && (err.message || err.description)) || (typeof err === 'string' ? err : JSON.stringify(err || {}));
const m = /\b(400|401|403|429|500|503)\b/.exec(String(message));
const status = m ? Number(m[1]) : null;

job.failed = true;
job.statusCode = status;
job.error = String(message).slice(0, 300);
job.more = false;
if ([400, 401, 403, 429].includes(status)) {
  state.runAbort = true;
  job.fatal = true;
}
return [{ json: job }];

// Scores every topic against its own history, finds breakout phrases and newcomer channels,
// and writes the new state. A topic with any failed or skipped search keeps its old state,
// so the next run catches up from the same watermark.
const cfg = $('Set Trend Search Config').first().json;
const state = $getWorkflowStaticData('global');
state.topics = state.topics || {};
state.phrases = state.phrases || {};

const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const RISING = num(cfg.risingRatio, 2);
const SPIKE = num(cfg.spikeRatio, 4);
const MIN_VIDEOS = num(cfg.minNewVideos, 5);
const MIN_RUNS = num(cfg.minRunsBeforeAlerts, 6);
const MIN_CH = num(cfg.minChannelsPerPhrase, 3);
const MAX_BREAKOUTS = num(cfg.maxBreakoutsPerTopic, 5);
const COOLDOWN_H = num(cfg.breakoutCooldownHours, 12);
const BASELINE_RUNS = num(cfg.baselineWindowRuns, 48);
const HISTORY_MAX = 168;   // one week of hourly runs
const now = Date.now();
const nowIso = new Date(now).toISOString();
// n8n reports editor runs as 'test' (older versions: 'manual'); the manual trigger check is a second signal
let manual = ['test', 'manual'].includes($execution.mode);
try { if ($('Manual Execution Trigger').isExecuted) manual = true; } catch (e) { /* node reference not available */ }

const STOP_EN = 'the and for with you your this that these those from have has had are was were will would can could should not but all any new how what why who when where which into out over under about more most just than then them they their our its it is in on at to of by as an be or if so do does did get got use using vs official video videos shorts short full part episode watch watching live today best top review reviews tutorial guide'.split(' ');
const STOP_DE = 'der die das den dem des ein eine einen einem einer und oder aber mit ohne fuer für von vom zu zum zur im in am an auf aus bei nach vor ueber über unter ist sind war waren wird werden kann koennen können nicht auch wie was wer wo warum neu neue neuer mehr sehr nur noch schon dann dass mein meine dein deine'.split(' ');
const EXTRA = String(cfg.extraStopwords || '').toLowerCase().split(/[\s,]+/).filter(Boolean);
const STOP = new Set([...STOP_EN, ...STOP_DE, ...EXTRA]);

const tokenize = t => String(t || '').toLowerCase()
  .replace(/https?:\/\/\S+/g, ' ')
  .replace(/[^\p{L}\p{N}\s'-]/gu, ' ')
  .split(/\s+/).filter(Boolean);
const isWord = w => w.length >= 3 && !/^\d+$/.test(w);
const median = a => { if (!a.length) return 0; const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const round = (v, d) => Number.isFinite(v) ? Number(v.toFixed(d)) : 0;

// Group job results by topic
const byTopic = {};
for (const item of $input.all()) {
  const j = item.json;
  (byTopic[j.topic] = byTopic[j.topic] || []).push(j);
}

const reports = [];
const problems = [];
let creditsUsed = 0;

for (const [topic, jobs] of Object.entries(byTopic)) {
  creditsUsed += jobs.reduce((s, j) => s + (j.pages || 0), 0);
  const failed = jobs.filter(j => j.failed);
  const skipped = jobs.filter(j => j.skipped);
  if (failed.length || skipped.length) {
    for (const j of failed) problems.push(topic + ' (' + j.format + '): ' + (j.error || 'request failed'));
    for (const j of skipped) problems.push(topic + ' (' + j.format + '): ' + (j.skipReason || 'skipped'));
    reports.push({ topic, level: 'incomplete', stage: 'n/a', score: 0, breakouts: [], examples: [] });
    continue;
  }

  const ts = state.topics[topic] = state.topics[topic] || { watermark: null, lastRunAt: null, runs: 0, history: [], channels: {} };
  const posts = [];
  const seenUrl = new Set();
  for (const j of jobs) for (const p of j.posts || []) {
    if (!seenUrl.has('youtube:' + p.url)) { seenUrl.add('youtube:' + p.url); posts.push(p); }
  }
  const capped = jobs.some(j => j.capped);

  const hours = ts.lastRunAt ? Math.min(24, Math.max(0.25, (now - ts.lastRunAt) / 3600000)) : 1;
  const videos = posts.length;
  const rate = videos / hours;

  // Channels (author_id is stable on YouTube, fall back to the channel name)
  const chKey = p => String(p.author_id || p.author || '');
  const channels = new Set(posts.map(chKey).filter(Boolean));
  const newcomers = [...channels].filter(c => !ts.channels[c]);
  const newcomerShare = channels.size ? newcomers.length / channels.size : 0;

  // Baseline = median rate of recent runs (robust against earlier spikes)
  const hist = ts.history.slice(-BASELINE_RUNS);
  const baseline = median(hist.map(h => h.rate));
  const ratio = rate / Math.max(baseline, 0.5);
  const warm = hist.length >= MIN_RUNS;
  const prev = hist.length ? hist[hist.length - 1] : null;
  const elevated = ratio >= RISING;

  let level = 'normal';
  if (!warm) level = 'learning';
  else if (videos >= MIN_VIDEOS && ratio >= SPIKE) level = 'spike';
  else if (videos >= MIN_VIDEOS && elevated) level = 'rising';
  else if (prev && prev.ratio >= RISING && rate < prev.rate * 0.75) level = 'cooling';

  let stage = 'normal';
  if (level === 'cooling') stage = 'fading';
  else if (level === 'spike' || level === 'rising') {
    if (!prev || prev.ratio < 1.2) stage = 'emerging';
    else if (rate >= prev.rate * 1.25) stage = 'accelerating';
    else if (rate <= prev.rate * 0.75) stage = 'fading';
    else stage = 'peaking';
  }

  // Breakout phrases: words and word pairs used by several different channels, compared with their own history
  const topicWords = new Set(tokenize(topic));
  const phr = state.phrases[topic] = state.phrases[topic] || {};
  const counts = {};
  const add = (ph, ch) => { (counts[ph] = counts[ph] || new Set()).add(ch); };
  for (const p of posts) {
    const ch = chKey(p);
    if (!ch) continue;
    const toks = tokenize(p.title).map(w => (isWord(w) && !STOP.has(w)) ? w : null);
    for (let i = 0; i < toks.length; i++) {
      if (!toks[i]) continue;
      if (!topicWords.has(toks[i])) add(toks[i], ch);
      if (toks[i + 1] && !(topicWords.has(toks[i]) && topicWords.has(toks[i + 1]))) add(toks[i] + ' ' + toks[i + 1], ch);
    }
  }
  let candidates = [];
  for (const [ph, set] of Object.entries(counts)) {
    if (set.size < MIN_CH) continue;
    const st = phr[ph];
    const br = set.size / Math.max(st ? st.ema : 0, 0.3);
    const coolingDown = st && st.alertedAt && (now - st.alertedAt) < COOLDOWN_H * 3600000;
    if (br >= 3 && !coolingDown) candidates.push({ phrase: ph, channels: set.size, ratio: round(br, 1), isNew: !st });
  }
  candidates.sort((a, b) => b.ratio - a.ratio || b.channels - a.channels || b.phrase.length - a.phrase.length);
  // Drop a single word when a selected pair containing it is about as widespread
  const picked = [];
  for (const c of candidates) {
    if (!c.phrase.includes(' ') && picked.some(p => p.phrase.includes(' ') && p.phrase.split(' ').includes(c.phrase) && p.channels >= c.channels * 0.8)) continue;
    picked.push(c);
    if (picked.length >= MAX_BREAKOUTS) break;
  }
  const breakouts = warm ? picked : [];

  // Update phrase memory (decayed average of distinct channels per run)
  for (const ph of Object.keys(phr)) {
    phr[ph].ema = phr[ph].ema * 0.9 + 0.1 * (counts[ph] ? counts[ph].size : 0);
  }
  for (const [ph, set] of Object.entries(counts)) {
    if (set.size >= 2 && !phr[ph]) phr[ph] = { ema: 0.1 * set.size };
  }
  for (const b of breakouts) if (phr[b.phrase]) phr[b.phrase].alertedAt = now;
  for (const ph of Object.keys(phr)) if (phr[ph].ema < 0.03) delete phr[ph];
  const keys = Object.keys(phr);
  if (keys.length > 400) keys.sort((a, b) => phr[a].ema - phr[b].ema).slice(0, keys.length - 400).forEach(k => delete phr[k]);

  // Examples: newest videos, newcomer channels first
  const newSet = new Set(newcomers);
  const examples = [...posts]
    .sort((a, b) => (newSet.has(chKey(b)) - newSet.has(chKey(a))) || String(b.posted_at).localeCompare(String(a.posted_at)))
    .slice(0, 3)
    .map(p => ({ title: p.title, url: p.url, author: p.author, posted_at: p.posted_at }));

  // Commit state for this topic
  const newest = posts.map(p => p.posted_at).filter(Boolean).sort().pop();
  ts.watermark = newest && (!ts.watermark || newest > ts.watermark) ? newest : (ts.watermark || nowIso);
  ts.lastRunAt = now;
  ts.runs = (ts.runs || 0) + 1;
  ts.history.push({ t: nowIso, rate: round(rate, 3), videos, channels: channels.size, ratio: round(ratio, 2), capped });
  ts.history = ts.history.slice(-HISTORY_MAX);
  for (const c of channels) ts.channels[c] = ts.channels[c] || nowIso;
  const chKeys = Object.keys(ts.channels);
  if (chKeys.length > 2000) chKeys.sort((a, b) => ts.channels[a].localeCompare(ts.channels[b])).slice(0, chKeys.length - 2000).forEach(k => delete ts.channels[k]);

  reports.push({
    topic, level, stage, videos, hours: round(hours, 1), rate: round(rate, 1), baseline: round(baseline, 1),
    ratio: round(ratio, 1), channels: channels.size, newcomers: newcomers.length,
    newcomerShare: round(newcomerShare, 2), score: round(ratio * (1 + newcomerShare), 1),
    capped, runsSoFar: hist.length + 1, runsNeeded: MIN_RUNS, breakouts, examples
  });
}

for (const d of state.runDropped || []) problems.push(d + ': skipped because "maxCreditsPerRun" is too low for all topics');

const actionable = r => ['spike', 'rising', 'cooling'].includes(r.level) || (r.breakouts && r.breakouts.length > 0);
const hasReport = manual || problems.length > 0 || reports.some(actionable);
reports.sort((a, b) => b.score - a.score);

return [{ json: {
  runAt: nowIso, manual, hasReport, reports, problems, creditsUsed,
  quotaRemaining: typeof state.runQuota === 'number' ? state.runQuota : null,
  maxTopics: num(cfg.maxTopicsInDigest, 10), chatId: cfg.telegramChatId
} }];

// Builds one Telegram digest (HTML parse mode, all text escaped) and splits it if it gets too long.
const s = $input.first().json;
const esc = t => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const MAX_LEN = 3500;   // Telegram limit is 4096 characters
const LABEL = { spike: 'SPIKE', rising: 'Rising', cooling: 'Cooling down', learning: 'Learning', normal: 'Normal', incomplete: 'Incomplete' };

const lines = [];
const learning = s.reports.filter(r => r.level === 'learning');
const visible = s.reports.filter(r => ['spike', 'rising', 'cooling'].includes(r.level) || (r.breakouts && r.breakouts.length));
const shown = s.manual ? s.reports.filter(r => r.level !== 'incomplete') : visible;

for (const r of shown.slice(0, s.maxTopics)) {
  lines.push('');
  lines.push('<b>' + esc(r.topic) + '</b> | ' + LABEL[r.level] + (r.stage && r.stage !== 'normal' ? ' | ' + r.stage : ''));
  if (r.level === 'learning') {
    lines.push('Collecting baseline: run ' + r.runsSoFar + ' of ' + r.runsNeeded + ' before alerts start. ' + r.videos + ' new videos this run.');
  } else {
    lines.push((r.capped ? 'At least ' : '') + r.videos + ' new videos in ' + r.hours + 'h (' + r.rate + '/h vs ' + r.baseline + '/h normal, ' + r.ratio + 'x). '
      + r.channels + ' channels, ' + r.newcomers + ' new to this topic.');
    if (r.capped) lines.push('Page cap reached, so there may be older unseen videos. The real volume is higher.');
  }
  for (const e of r.examples || []) {
    lines.push('• <a href="' + esc(e.url) + '">' + esc(e.title || '(untitled)') + '</a> (' + esc(e.author) + ')');
  }
  if (r.breakouts && r.breakouts.length) {
    lines.push('<i>Emerging sub-topics:</i>');
    for (const b of r.breakouts) lines.push('• ' + esc(b.phrase) + ' (' + b.channels + ' channels' + (b.isNew ? ', new' : ', ' + b.ratio + 'x usual') + ')');
  }
}
if (!s.manual && learning.length) lines.push('\nStill learning baselines for ' + learning.length + ' topic' + (learning.length === 1 ? '' : 's') + '.');
if (s.problems.length) {
  lines.push('\n<b>Problems in this run</b>');
  for (const p of s.problems.slice(0, 10)) lines.push('• ' + esc(p));
  lines.push('Check the RecentReborn credential, plan and quota. Affected topics keep their old state and catch up on the next successful run.');
}
if (s.manual) lines.push('\nManual test run: state is not saved, so baselines only build on scheduled runs of the activated workflow.');
lines.push('\nCredits used: ' + s.creditsUsed + (s.quotaRemaining !== null ? ' | Daily quota remaining: ' + s.quotaRemaining : ''));

const header = '📈 <b>YouTube trend report</b> | ' + esc(s.runAt.slice(0, 16).replace('T', ' ')) + ' UTC';
const messages = [];
let chunk = header;
for (const line of lines) {
  if ((chunk + '\n' + line).length > MAX_LEN) {
    messages.push({ json: { chatId: s.chatId, text: chunk } });
    chunk = header + ' (cont.)';
  }
  chunk += '\n' + line;
}
messages.push({ json: { chatId: s.chatId, text: chunk } });
return messages;
